WITH q AS (SELECT d.department_id,d.department_name,d.description,COUNT(p.position_id) AS position_count FROM public.department d LEFT JOIN public.position p ON p.department_id=d.department_id GROUP BY d.department_id,d.department_name,d.description ORDER BY d.department_name LIMIT 10 OFFSET 0) SELECT jsonb_build_object('rows',count(*),'md5',md5(COALESCE(string_agg(to_jsonb(q)::text,E'\n' ORDER BY to_jsonb(q)::text),''))) FROM q;
